#!/bin/bash
set -e
CYAN='\e[1;36m'; GREEN='\e[1;32m'; RED='\e[1;31m'; NC='\e[0m'
if [ "$(id -u)" -ne 0 ]; then echo -e "${RED}[-] Please run as root (sudo).${NC}"; exit 1; fi
echo -e "${CYAN}[*] Installing NexusNet Personal Edition v2.0...${NC}"
if command -v apt-get >/dev/null 2>&1; then
  apt-get update -y >/dev/null 2>&1 || true
  apt-get install -y python3 python3-pip curl tor tor-geoipdb >/dev/null 2>&1 || true
fi
pip3 install --break-system-packages 'requests[socks]' >/dev/null 2>&1 || pip3 install 'requests[socks]' >/dev/null 2>&1 || true
echo -e "${CYAN}[*] Writing NexusNet...${NC}"
B64_FILE=$(mktemp)
trap 'rm -f "$B64_FILE"' EXIT
cat > "$B64_FILE" << 'B64EOF'

B64EOF
python3 - "$B64_FILE" << 'PY'
import base64, sys, re, os
with open(sys.argv[1], "r") as f:
    data = base64.b64decode(f.read().strip())
with open("/usr/local/bin/nexusnet", "wb") as out:
    out.write(data)
print("OK")
src = data.decode("utf-8", errors="replace")
m = re.search(r'b64_data\s*=\s*"""([A-Za-z0-9+/=\n]+)"""', src)
if m:
    pdata = base64.b64decode(m.group(1).strip())
    open("/usr/local/bin/panel-tools", "wb").write(pdata)
    os.chmod("/usr/local/bin/panel-tools", 0o755)
    print("panel-tools OK")
PY
chmod +x /usr/local/bin/nexusnet
ln -sf /usr/local/bin/nexusnet /usr/local/bin/NexusNet 2>/dev/null || true
echo -e "${GREEN}[+] Installed successfully! (v2.0)${NC}"
echo -e "${GREEN}[+] Run with:  nexusnet${NC}"
echo
exec /usr/local/bin/nexusnet </dev/tty
